{
  "root_causes": [
    {
      "service": "ts-order-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND span_name='SELECT Order' GROUP BY 1",
          "claim": "ts-order-service 'SELECT Order' DB spans have p50 about 1.6 s and p95 about 6.3 s in the abnormal period, versus about 1.1 ms p50 in normal."
        },
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, round(approx_quantile(duration,0.5)/1e6,1) p50_ms, round(approx_quantile(duration,0.95)/1e6,1) p95_ms FROM abnormal_traces WHERE service_name='ts-order-service' AND span_name='SELECT ts.orders' GROUP BY 1",
          "claim": "The child client DB span 'SELECT ts.orders' under SELECT Order takes seconds (p50 around 4.8 s) in abnormal traces."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, round(avg(value),4) avgv FROM abnormal_metrics WHERE service_name='ts-order-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2 UNION ALL SELECT 'nor', metric, round(avg(value),4) FROM normal_metrics WHERE service_name='ts-order-service' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2",
          "claim": "ts-order-service container CPU and memory are flat or lower in abnormal than normal, so the process itself is not resource-saturated."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' p, metric, round(avg(value),4) avgv FROM abnormal_metrics WHERE service_name='mysql' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2 UNION ALL SELECT 'nor', metric, round(avg(value),4) FROM normal_metrics WHERE service_name='mysql' AND metric IN ('container.cpu.usage','container.memory.working_set') GROUP BY 1,2",
          "claim": "mysql CPU and memory are unchanged or lower in the abnormal period, so the database server is not the saturated resource."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-order-service",
      "to": "ts-seat-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-seat-service' AND c.service_name='ts-order-service' GROUP BY 1,2",
          "claim": "Seat-service calls to order-service take about 973 ms p50 in the abnormal period, with seat's own time unchanged."
        }
      ]
    },
    {
      "from": "ts-order-service",
      "to": "ts-security-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-security-service' AND c.service_name='ts-order-service' GROUP BY 1,2",
          "claim": "Security-service calls to order-service take about 10.1 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-order-service",
      "to": "ts-inside-payment-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-inside-payment-service' AND c.service_name='ts-order-service' GROUP BY 1,2",
          "claim": "Inside-payment-service calls to order-service take about 3.7 s p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-seat-service",
      "to": "ts-travel-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-service' AND c.service_name='ts-seat-service' GROUP BY 1,2",
          "claim": "Travel-service calls to seat-service take about 1.2 s p50 in the abnormal period, inheriting the order delay."
        }
      ]
    },
    {
      "from": "ts-travel-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel-service' GROUP BY 1,2",
          "claim": "Route-plan-service calls to travel-service take about 38 ms p50 in the abnormal period, with the delay carried from seat."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan-service calls to route-plan-service take about 338 ms p50 in the abnormal period."
        }
      ]
    },
    {
      "from": "ts-order-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name caller, c.service_name callee, count(*) n, round(approx_quantile(c.duration,0.5)/1e6,1) callee_p50_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-ui-dashboard' AND c.service_name='ts-order-service' GROUP BY 1,2",
          "claim": "UI-dashboard calls to order-service show the order delay directly in the abnormal period."
        }
      ]
    }
  ]
}
